#!/bin/sh
# Rebuilds crates/ui/assets/tabler.ttf (17 kB) and crates/ui/src/icon_table.rs from the full Tabler icon font.
# Usage: tools/subset_icons.sh /path/to/full/tabler.ttf /path/to/tabler.json
# (the full font and its name->codepoint json ship with the Noctalia shell: lib/assets/fonts/)
set -eu
font=$1; json=$2
names="sun moon cloud-sun cloud cloud-fog cloud-snow cloud-storm cloud-rain umbrella download circle-check alert-triangle bell bell-ringing battery battery-1 battery-charging music player-play player-pause player-skip-back player-skip-forward hourglass target calendar-event volume volume-3 volume-2 sun-high brightness-up microphone video screen-share bluetooth wifi moon-stars coffee clipboard settings x send mail-forward cpu device-desktop plane-tilt arrows-exchange message-reply trash bell-off plug wifi-off bluetooth-off bolt leaf gauge headphones device-speaker brightness-half arrow-left chevron-left chevron-right external-link clipboard-text plus settings brand-apple refresh home calendar adjustments-horizontal terminal-2 search clock alarm battery-2 battery-3 battery-4 battery-off headset device-airpods mouse keyboard bell-z git-branch circle-x check headphones-off device-gamepad-2 minus toggle-right star star-filled file upload device-laptop device-mobile devices microphone-off mail map-pin route car walk bus bike alert-circle activity chart-donut history eye ban player-pause flame train"
python3 - "$json" $names <<'PY' > ${TMPDIR:-/tmp}/island-icons.txt
import json, sys
d = json.load(open(sys.argv[1]))
rows = sorted((n, int(d[n]["codepoint"][2:], 16)) for n in set(sys.argv[2:]))
print(",".join("U+%X" % c for _, c in rows))
with open("crates/ui/src/icon_table.rs", "w") as f:
    f.write("// Generated by tools/subset_icons.sh from Tabler icons (MIT): name -> codepoint in assets/tabler.ttf.\npub const ICONS: &[(&str, u32)] = &[\n")
    for n, c in rows:
        f.write('    ("%s", 0x%X),\n' % (n, c))
    f.write("];\n")
PY
pyftsubset "$font" --unicodes="$(cat ${TMPDIR:-/tmp}/island-icons.txt)" --output-file=crates/ui/assets/tabler.ttf
